      cut=methName.indexOf('(');
      if (cut > 0)       methName=methName.substring(0,cut);
      meth=obj.getClass().getMethod(methName,NULL_SIG);
      obj=meth.invoke(obj,NULL_ARGS);
    }
    return obj;
  }
 catch (  Exception e) {
    throw new Exception("Could not resolve call: " + target + "."+ method+ "\n"+ e);
  }
}

