  Entry e=table[index];
  if (e != null) {
    if ((e.hash == hash) && e.match(c)) {
      Object old=e.get();
      table[index]=new Entry(hash,c,value,e.next);
      return (Value)old;
    }
    Entry o=e;
    e=e.next;
    while (e != null) {
      if ((e.hash == hash) && e.match(c)) {
        Object old=e.get();
        e=new Entry(hash,c,value,e.next);
        o.next=e;
