      o=e;
      e=e.next;
    }
  }
  int len=table.length;
  if (count++ >= (len - (len >> 2))) {
    rehash();
    index=hash % table.length;
  }
  table[index]=new Entry(hash,c,value,table[index]);
  return null;
}

