    return null;
  }
  if (factory == null) {
    factory=ContextFactory.getGlobal();
  }
  final Scriptable scope=f.getParentScope();
  if (argsToWrap == 0) {
    return Context.call(factory,f,scope,thisObj,args);
  }
  Context cx=Context.getCurrentContext();
  if (cx != null) {
    return doCall(cx,scope,thisObj,f,args,argsToWrap);
  }
  return factory.call(cx2 -> doCall(cx2,scope,thisObj,f,args,argsToWrap));
}

protected void updateHoverHandles(DrawingView view,Figure f){
  if (f != hoverFigure) {
    Rectangle r=null;
    if (hoverFigure != null && hoverFigure.isSelectable()) {
      for (      Handle h : hoverHandles) {
        if (r == null) {
          r=h.getDrawingArea();
        }
 else {
          r.add(h.getDrawingArea());
        }
        h.setView(null);
        h.dispose();
      }
      hoverHandles.clear();
    }
    hoverFigure=f;
    if (hoverFigure != null) {
      hoverHandles.addAll(hoverFigure.createHandles(-1));
      for (      Handle h : hoverHandles) {
        h.setView(view);
        if (r == null) {
          r=h.getDrawingArea();
        }
 else {
          r.add(h.getDrawingArea());
        }
      }
    }
    if (r != null) {
      r.grow(1,1);
      fireAreaInvalidated(r);
    }
  }
}

