    i=(r + l) >>> 1;
    if (lessThan(i,l)) {
      swap(l,i);
    }
    if (lessThan(r,l)) {
      swap(l,r);
    }
    if (lessThan(r,i)) {
      swap(i,r);
    }
    j=r - 1;
    swap(i,j);
    i=l;
    v=j;
    for (; ; ) {
