    int pos=bytesPerRow * y + size * x;
    for (int k=0; k < size; ++k)     image[pos + k]=(byte)(data[k + offset] >>> 8);
  }
 else {
    int pos=bytesPerRow * y + x / (8 / bitDepth);
    int v=data[offset] << (8 - bitDepth * (x % (8 / bitDepth)) - bitDepth);
    image[pos]|=(byte)v;
  }
}

