@Override public void propertyChange(PropertyChangeEvent evt){
  String name=evt.getPropertyName();
  if ((name == null && DrawingEditor.ACTIVE_VIEW_PROPERTY == null) || (name != null && name.equals(DrawingEditor.ACTIVE_VIEW_PROPERTY))) {
    DrawingView view=(DrawingView)evt.getOldValue();
    if (view != null) {
      view.removePropertyChangeListener(this);
      if (view.getDrawing() != null) {
        view.getDrawing().removeDrawingListener(this);
      }
    }
    view=(DrawingView)evt.getNewValue();
    if (view != null) {
      view.addPropertyChangeListener(this);
      if (view.getDrawing() != null) {
        view.getDrawing().addDrawingListener(this);
      }
    }
    component.repaint();
  }
 else   if ((name == null && DrawingView.DRAWING_PROPERTY == null) || (name != null && name.equals(DrawingView.DRAWING_PROPERTY))) {
    Drawing drawing=(Drawing)evt.getOldValue();
    if (drawing != null) {
      drawing.removeDrawingListener(this);
    }
    drawing=(Drawing)evt.getNewValue();
    if (drawing != null) {
      drawing.addDrawingListener(this);
    }
    component.repaint();
  }
 else {
    component.repaint();
  }
}

