public static ObjectInfo[] duplicateAll(ObjectInfo info[]){
  ObjectInfo newobj[]=new ObjectInfo[info.length];
  HashMap<ObjectInfo,ObjectInfo> objectMap=new HashMap<ObjectInfo,ObjectInfo>();
  for (int i=0; i < newobj.length; i++) {
    newobj[i]=info[i].duplicate(info[i].getObject().duplicate());
    objectMap.put(info[i],newobj[i]);
  }
  for (int i=0; i < info.length; i++)   for (int k=info[i].getChildren().length - 1; k >= 0; k--) {
    int j;
    for (j=0; j < info.length && info[j] != info[i].getChildren()[k]; j++)     ;
    if (j < info.length)     newobj[i].addChild(newobj[j],0);
  }
  for (int i=0; i < newobj.length; i++)   if (newobj[i].tracks != null)   for (int j=0; j < newobj[i].tracks.length; j++)   newobj[i].tracks[j].updateObjectReferences(objectMap);
  return newobj;
}

public void replaceFromToWithFromTo(int from,int to,AbstractFloatList other,int otherFrom,int otherTo){
  if (otherFrom > otherTo) {
    throw new IndexOutOfBoundsException("otherFrom: " + otherFrom + ", otherTo: "+ otherTo);
  }
  if (this == other && to - from != otherTo - otherFrom) {
    replaceFromToWithFromTo(from,to,partFromTo(otherFrom,otherTo),0,otherTo - otherFrom);
    return;
  }
  int length=otherTo - otherFrom + 1;
  int diff=length;
  int theLast=from - 1;
  if (to >= from) {
    diff-=(to - from + 1);
    theLast=to;
  }
  if (diff > 0) {
    beforeInsertDummies(theLast + 1,diff);
  }
 else {
    if (diff < 0) {
      removeFromTo(theLast + diff,theLast - 1);
    }
  }
  if (length > 0) {
    replaceFromToWithFrom(from,from + length - 1,other,otherFrom);
  }
}

