class SortRecord implements Comparable {
    public ObjectInfo object;
    public double depth;
    public boolean isTransparent;
    SortRecord(    ObjectInfo object){
      this.object=object;
      depth=theCamera.getObjectToView().times(object.getBounds().getCenter()).z;
