    @Override public int compareTo(    Object o){
      SortRecord other=(SortRecord)o;
      if (isTransparent == other.isTransparent) {
        if (depth < other.depth)         return -1;
        if (depth == other.depth)         return 0;
        return 1;
      }
      if (isTransparent)       return 1;
      return -1;
    }
  }
