  if (rem == 1) {
    long value=getQuick(0);
    if (value != 0) {
      indexList.add(0);
      valueList.add(value);
    }
  }
  for (int i=rem; i < size; i+=2) {
    long value=getQuick(i);
    if (value != 0) {
      indexList.add(i);
      valueList.add(value);
    }
    value=getQuick(i + 1);
    if (value != 0) {
      indexList.add(i + 1);
      valueList.add(value);
    }
  }
}

public static void logExceptionLocation(PrintWriter pw,Throwable exception){
