    pw.println("exception:" + exception.getMessage());
    pw.println("root-cause:" + ((null != cause) ? cause.getMessage() : "null"));
    logSourceLine(pw,locator);
  }
 else {
    pw.print("SystemId-Unknown:locator-unavailable: ");
    pw.println("exception:" + exception.getMessage());
    pw.println("root-cause:" + ((null != cause) ? cause.getMessage() : "null"));
  }
}

