  for (  Repository repository : repositories) {
    validateStringNotEmpty(prefix,prefix2,"id",problems,Severity.ERROR,Version.V20,repository.getId(),null,repository);
    if (validateStringNotEmpty(prefix,prefix2,"[" + repository.getId() + "].url",problems,Severity.ERROR,Version.V20,repository.getUrl(),null,repository)) {
      Matcher m=EXPRESSION_NAME_PATTERN.matcher(repository.getUrl());
      while (m.find()) {
        if (!("basedir".equals(m.group(1)) || "project.basedir".equals(m.group(1)))) {
          validateStringNoExpression(prefix + prefix2 + "["+ repository.getId()+ "].url",problems,Severity.ERROR,Version.V40,repository.getUrl(),repository);
          break;
        }
      }
    }
    String key=repository.getId();
    Repository existing=index.get(key);
    if (existing != null) {
      Severity errOn30=getSeverity(request,ModelBuildingRequest.VALIDATION_LEVEL_MAVEN_3_0);
      addViolation(problems,errOn30,Version.V20,prefix + prefix2 + "id",null,"must be unique: " + repository.getId() + " -> "+ existing.getUrl()+ " vs "+ repository.getUrl(),repository);
    }
 else {
      index.put(key,repository);
    }
  }
}

