    WireframeMesh cached=cachedWire.get();
    if (cached != null)     return cached;
  }
  if (smoothingMethod == INTERPOLATING || smoothingMethod == APPROXIMATING) {
    split=new boolean[edge.length];
    for (i=0; i < split.length; i++)     split[i]=true;
    if (smoothingMethod == INTERPOLATING)     mesh=subdivideButterfly(mesh,split,ArtOfIllusion.getPreferences().getInteractiveSurfaceError());
 else     mesh=subdivideLoop(mesh,split,ArtOfIllusion.getPreferences().getInteractiveSurfaceError());
    v=mesh.vertex;
    e=mesh.edge;
  }
 else {
    v=vertex;
    e=edge;
  }
  point=new Vec3[v.length];
  from=new int[e.length];
  to=new int[e.length];
  for (i=0; i < v.length; i++)   point[i]=v[i].r;
  for (i=0; i < e.length; i++) {
    from[i]=e[i].v1;
    to[i]=e[i].v2;
  }
  WireframeMesh wire=new WireframeMesh(point,from,to);
  cachedWire=new SoftReference<WireframeMesh>(wire);
