int compareRowForInsertOrDelete(Session session,Row newRow,Row existingRow,boolean useRowId,int start){
  Object[] a=newRow.getData();
  Object[] b=existingRow.getData();
  for (int j=start; j < colIndex.length; j++) {
    int i=colTypes[j].compare(session,a[colIndex[j]],b[colIndex[j]]);
    if (i != 0) {
      if (isSimpleOrder) {
        return i;
      }
      boolean nulls=a[colIndex[j]] == null || b[colIndex[j]] == null;
      if (colDesc[j] && !nulls) {
        i=-i;
      }
      if (nullsLast[j] && nulls) {
        i=-i;
      }
      return i;
    }
  }
  if (start == 0 && table.isSystemVersioned) {
    TimestampData newVersion=newRow.getSystemEndVersion();
    TimestampData existingVersion=existingRow.getSystemEndVersion();
    int compare=Type.SQL_TIMESTAMP_WITH_TIME_ZONE.compare(session,newVersion,existingVersion);
    if (compare == 0) {
      if (newVersion.getSeconds() != DateTimeType.epochLimitSeconds) {
        useRowId=true;
      }
    }
 else {
      return compare;
    }
  }
  if (useRowId) {
    long diff=newRow.getPos() - existingRow.getPos();
    return diff == 0L ? 0 : diff > 0L ? 1 : -1;
  }
  return 0;
}

