public static int binarySearchFromTo(byte[] list,byte key,int from,int to){
  byte midVal;
  while (from <= to) {
    int mid=(from + to) / 2;
    midVal=list[mid];
    if (midVal < key)     from=mid + 1;
 else     if (midVal > key)     to=mid - 1;
 else     return mid;
  }
  return -(from + 1);
}

