protected static void sampleMethodA(long n,long N,int count,long low,long[] values,int fromIndex,DoubleRandomEngine randomGenerator){
  double V, quot, Nreal, top;
  long S;
  long chosen=-1 + low;
  top=N - n;
  Nreal=N;
  while (n >= 2 && count > 0) {
    V=randomGenerator.raw();
    S=0;
    quot=top / Nreal;
    while (quot > V) {
      S++;
      top--;
      Nreal--;
      quot=(quot * top) / Nreal;
    }
    chosen+=S + 1;
    values[fromIndex++]=chosen;
    count--;
    Nreal--;
    n--;
  }
  if (count > 0) {
    S=(long)(Math.round(Nreal) * randomGenerator.raw());
    chosen+=S + 1;
    values[fromIndex]=chosen;
  }
}

