Node decompileFunctionHeader(FunctionNode fn){
  Node mexpr=null;
  if (fn.getFunctionName() != null) {
    decompiler.addName(fn.getName());
  }
 else   if (fn.getMemberExprNode() != null) {
    mexpr=transform(fn.getMemberExprNode());
  }
  boolean isArrow=fn.getFunctionType() == FunctionNode.ARROW_FUNCTION;
  boolean noParen=isArrow && fn.getLp() == -1;
  if (!noParen) {
    decompiler.addToken(Token.LP);
  }
  List<AstNode> params=fn.getParams();
  for (int i=0; i < params.size(); i++) {
    decompile(params.get(i));
    if (i < params.size() - 1) {
      decompiler.addToken(Token.COMMA);
    }
  }
  if (!noParen) {
    decompiler.addToken(Token.RP);
  }
  if (isArrow) {
    decompiler.addToken(Token.ARROW);
  }
  if (!fn.isExpressionClosure()) {
    decompiler.addEOL(Token.LC);
  }
  return mexpr;
}

public static void copyMoveSegment(Object source,Object dest,int size,int index,int segmentSize,int destIndex){
  boolean forward=index < destIndex;
  int sliceSize=forward ? index : destIndex;
  System.arraycopy(source,0,dest,0,sliceSize);
  sliceSize=forward ? size - destIndex - segmentSize : size - index - segmentSize;
  int sliceIndex=forward ? destIndex + segmentSize : index + segmentSize;
  System.arraycopy(source,sliceIndex,dest,sliceIndex,sliceSize);
  System.arraycopy(source,index,dest,destIndex,segmentSize);
  sliceSize=Math.abs(index - destIndex);
  sliceIndex=forward ? index + segmentSize : destIndex;
  int targetSliceIndex=forward ? index : destIndex + segmentSize;
  System.arraycopy(source,sliceIndex,dest,targetSliceIndex,sliceSize);
}

