  int i=0, start=0, end;
  char c;
  outer:   while (i < len) {
    while (valuesString.charAt(i) == ' ') {
      i++;
      if (i == len) {
        break outer;
      }
    }
    start=i++;
    if (i < len) {
      c=valuesString.charAt(i);
      while (c != ';') {
        i++;
        if (i == len) {
          break;
        }
        c=valuesString.charAt(i);
      }
    }
    end=i++;
    String valueString=valuesString.substring(start,end);
    AnimatableValue value=parseValue(valueString,type,target);
