private String basedir(String url){
  String retValue=null;
  if (protocol.equalsIgnoreCase("file")) {
    retValue=url.substring(protocol.length() + 1);
    retValue=decode(retValue);
    if (retValue.startsWith("//")) {
      retValue=retValue.substring(2);
      if (retValue.length() >= 2 && (retValue.charAt(1) == '|' || retValue.charAt(1) == ':')) {
        retValue=retValue.charAt(0) + ":" + retValue.substring(2);
      }
 else {
        int index=retValue.indexOf('/');
        if (index >= 0) {
          retValue=retValue.substring(index + 1);
        }
        if (retValue.length() >= 2 && (retValue.charAt(1) == '|' || retValue.charAt(1) == ':')) {
          retValue=retValue.charAt(0) + ":" + retValue.substring(2);
        }
 else         if (index >= 0) {
          retValue="/" + retValue;
        }
      }
    }
    if (retValue.length() >= 2 && retValue.charAt(1) == '|') {
      retValue=retValue.charAt(0) + ":" + retValue.substring(2);
    }
    retValue=new File(retValue).getPath();
  }
  if (retValue == null) {
    retValue="/";
  }
  return retValue.trim();
}

public int nextNode(){
  if (m_foundLast)   return DTM.NULL;
  int earliestNode=DTM.NULL;
  if (null != m_iterators) {
    int n=m_iterators.length;
    int iteratorUsed=-1;
    for (int i=0; i < n; i++) {
      int node=m_iterators[i].getCurrentNode();
      if (DTM.NULL == node)       continue;
 else       if (DTM.NULL == earliestNode) {
        iteratorUsed=i;
        earliestNode=node;
      }
 else {
        if (node == earliestNode) {
          m_iterators[i].nextNode();
        }
 else {
          DTM dtm=getDTM(node);
          if (dtm.isNodeAfter(node,earliestNode)) {
            iteratorUsed=i;
            earliestNode=node;
          }
        }
      }
    }
    if (DTM.NULL != earliestNode) {
      m_iterators[iteratorUsed].nextNode();
      incrementCurrentPos();
    }
 else     m_foundLast=true;
  }
  m_lastFetched=earliestNode;
  return earliestNode;
}

