@Override public float[] fromCIEXYZ(float[] xyz,float[] colorvalue){
  double X=xyz[0];
  double Y=xyz[1];
  double Z=xyz[2];
  double xr=X / Xr;
  double yr=Y / Yr;
  double zr=Z / Zr;
  double fx, fy, fz;
  if (xr > EPS) {
    fx=Math.pow(xr,1d / 3d);
  }
 else {
    fx=(K * xr + 16d) / 116d;
  }
  if (yr > EPS) {
    fy=Math.pow(yr,1d / 3d);
  }
 else {
    fy=(K * yr + 16d) / 116d;
  }
  if (zr > EPS) {
    fz=Math.pow(zr,1d / 3d);
  }
 else {
    fz=(K * zr + 16) / 116;
  }
  double L=116d * fy - 16;
  double a=500d * (fx - fy);
  double b=200d * (fy - fz);
  double C=Math.sqrt(a * a + b * b);
  double H=Math.atan2(b,a);
  colorvalue[0]=(float)L;
  colorvalue[1]=(float)C;
  colorvalue[2]=(float)(H * 180 / PI);
  return colorvalue;
}

