  PdfFont font=PdfFontFactory.createFont(StandardFonts.HELVETICA);
  float x=document.getDefaultPageSize().getWidth() / 2;
  float y=document.getDefaultPageSize().getHeight() / 2;
  canvas.concatMatrix(AffineTransform.getTranslateInstance(x,y));
  canvas.moveTo(-10,0).lineTo(10,0).moveTo(0,-10).lineTo(0,10).stroke();
  canvas.beginText().setFontAndSize(font,12).concatMatrix(AffineTransform.getRotateInstance((float)(rotation / 180f * Math.PI))).showText(text1);
  if (moveTextToNextLine)   canvas.moveText(0,moveTextDelta);
 else   canvas.concatMatrix(AffineTransform.getTranslateInstance(moveTextDelta,0));
  canvas.showText(text2);
  canvas.endText();
  document.close();
  return byteStream.toByteArray();
}

