public void getNegativeValues(final IntArrayList indexList,final DoubleArrayList valueList){
  boolean fillIndexList=indexList != null;
  boolean fillValueList=valueList != null;
  if (fillIndexList)   indexList.clear();
  if (fillValueList)   valueList.clear();
  int rem=size % 2;
  int idx=zero;
  if (rem == 1) {
    double value=elements[idx];
    if (value < 0) {
      if (fillIndexList) {
        indexList.add(0);
      }
      if (fillValueList) {
        valueList.add(value);
      }
    }
    idx+=stride;
  }
  for (int i=rem; i < size; i+=2) {
    double value=elements[idx];
    if (value < 0) {
      if (fillIndexList) {
        indexList.add(i);
      }
      if (fillValueList) {
        valueList.add(value);
      }
    }
    idx+=stride;
    value=elements[idx];
    if (value < 0) {
      if (fillIndexList) {
        indexList.add(i + 1);
      }
      if (fillValueList) {
        valueList.add(value);
      }
    }
    idx+=stride;
  }
}

