private static void readRLE4(BmpParameters bmp) throws java.io.IOException {
  int imSize=(int)bmp.imageSize;
  if (imSize == 0) {
    imSize=(int)(bmp.bitmapFileSize - bmp.bitmapOffset);
  }
  byte[] values=new byte[imSize];
  int bytesRead=0;
  while (bytesRead < imSize) {
    bytesRead+=bmp.inputStream.read(values,bytesRead,imSize - bytesRead);
  }
  byte[] val=decodeRLE(false,values,bmp);
  if (bmp.isBottomUp) {
    byte[] inverted=val;
    val=new byte[bmp.width * bmp.height];
    int l=0, index, lineEnd;
    for (int i=bmp.height - 1; i >= 0; i--) {
      index=i * bmp.width;
      lineEnd=l + bmp.width;
      while (l != lineEnd) {
        val[l++]=inverted[index++];
      }
    }
  }
  int stride=(bmp.width + 1) / 2;
  byte[] bdata=new byte[stride * bmp.height];
  int ptr=0;
  int sh=0;
  for (int h=0; h < bmp.height; ++h) {
    for (int w=0; w < bmp.width; ++w) {
      if ((w & 1) == 0)       bdata[sh + w / 2]=(byte)(val[ptr++] << 4);
 else       bdata[sh + w / 2]|=(byte)(val[ptr++] & 0x0f);
    }
    sh+=stride;
  }
  indexedModel(bdata,4,4,bmp);
}

public static String validateProperty(String key,String value,PropertyMeta meta){
  if (meta.propClass.equals("Boolean")) {
    value=value.toLowerCase();
    if (value.equals("true") || value.equals("false")) {
      return null;
    }
    return "invalid boolean value for property: " + key;
  }
  if (meta.propClass.equals("String")) {
    return null;
  }
  if (meta.propClass.equals("Long")) {
    return null;
  }
  if (meta.propClass.equals("Integer")) {
    try {
      int number=Integer.parseInt(value);
      if (meta.propIsRange) {
        int low=meta.propRangeLow;
        int high=meta.propRangeHigh;
        if (number < low || high < number) {
          return "value outside range for property: " + key;
        }
      }
      if (meta.propValues != null) {
        int[] values=meta.propValues;
        if (ArrayUtil.find(values,number) == -1) {
          return "value not supported for property: " + key;
        }
      }
    }
 catch (    NumberFormatException e) {
      return "invalid integer value for property: " + key;
    }
    return null;
  }
  return null;
}

