protected void checkResources(PdfDictionary resources){
  if (resources == null)   return;
  PdfDictionary xObjects=resources.getAsDictionary(PdfName.XObject);
  PdfDictionary shadings=resources.getAsDictionary(PdfName.Shading);
  PdfDictionary patterns=resources.getAsDictionary(PdfName.Pattern);
  if (xObjects != null) {
    for (    PdfObject xObject : xObjects.values()) {
      PdfStream xObjStream=(PdfStream)xObject;
      PdfObject subtype=null;
      boolean isFlushed=xObjStream.isFlushed();
      if (!isFlushed) {
        subtype=xObjStream.get(PdfName.Subtype);
      }
      if (PdfName.Image.equals(subtype) || isFlushed) {
        checkImage(xObjStream,resources.getAsDictionary(PdfName.ColorSpace));
      }
 else       if (PdfName.Form.equals(subtype)) {
        checkFormXObject(xObjStream);
      }
    }
  }
  if (shadings != null) {
    for (    PdfObject shading : shadings.values()) {
      PdfDictionary shadingDict=(PdfDictionary)shading;
      if (!isAlreadyChecked(shadingDict)) {
        checkColorSpace(PdfColorSpace.makeColorSpace(shadingDict.get(PdfName.ColorSpace)),resources.getAsDictionary(PdfName.ColorSpace),true,null);
      }
    }
  }
  if (patterns != null) {
    for (    PdfObject p : patterns.values()) {
      if (p.isStream()) {
        PdfStream pStream=(PdfStream)p;
        if (!isAlreadyChecked(pStream)) {
          checkResources(pStream.getAsDictionary(PdfName.Resources));
        }
      }
    }
  }
}

@Override public Object execIdCall(IdFunctionObject f,Context cx,Scriptable scope,Scriptable thisObj,Object[] args){
  if (!f.hasTag(MAP_TAG)) {
    return super.execIdCall(f,cx,scope,thisObj,args);
  }
  int id=f.methodId();
switch (id) {
case Id_constructor:
    if (thisObj == null) {
      NativeWeakMap nm=new NativeWeakMap();
      nm.instanceOfWeakMap=true;
      if (args.length > 0) {
        NativeMap.loadFromIterable(cx,scope,nm,NativeMap.key(args));
      }
      return nm;
    }
  throw ScriptRuntime.typeErrorById("msg.no.new","WeakMap");
case Id_delete:
return realThis(thisObj,f).js_delete(NativeMap.key(args));
case Id_get:
return realThis(thisObj,f).js_get(NativeMap.key(args));
case Id_has:
return realThis(thisObj,f).js_has(NativeMap.key(args));
case Id_set:
return realThis(thisObj,f).js_set(NativeMap.key(args),args.length > 1 ? args[1] : Undefined.instance);
}
throw new IllegalArgumentException("WeakMap.prototype has no method: " + f.getFunctionName());
}

