public static String groupnameCharToHtml(String raw){
  if (raw == null)   return null;
  raw=convertFormattingCharacters(raw);
  char[] chars=raw.toCharArray();
  StringBuffer encoded=new StringBuffer();
  for (int i=0; i < chars.length; i++) {
    char c=chars[i];
    if (c == '<')     encoded.append("&lt;");
 else     if (c == '>')     encoded.append("&gt;");
 else     if (c == ' ')     encoded.append("&#160;");
 else     if (c < 128)     encoded.append(c);
 else     if (c < 256)     encoded.append(htmlEntities[c - 128]);
 else {
      encoded.append("&#");
      encoded.append((int)c);
      encoded.append(";");
    }
  }
  return encoded.toString();
}

