public Collection<IvyNode> resolveConflicts(IvyNode parent,Collection<IvyNode> conflicts){
  if (conflicts.size() < 2) {
    return conflicts;
  }
  for (  IvyNode node : conflicts) {
    DependencyDescriptor dd=node.getDependencyDescriptor(parent);
    if (dd != null && dd.isForce() && parent.getResolvedId().equals(dd.getParentRevisionId())) {
      return Collections.singleton(node);
    }
  }
  for (  IvyNode node : conflicts) {
    ModuleRevisionId modRev=node.getResolvedId();
    if (getSettings().getVersionMatcher().isDynamic(modRev)) {
      return null;
    }
  }
  List<IvyNode> unevicted=new ArrayList<>();
  for (  IvyNode node : conflicts) {
    if (!node.isCompletelyEvicted()) {
      unevicted.add(node);
    }
  }
  if (unevicted.size() > 0) {
    conflicts=unevicted;
  }
  try {
    IvyNodeArtifactInfo latest=(IvyNodeArtifactInfo)getStrategy().findLatest(toArtifactInfo(conflicts),null);
    if (latest != null) {
      return Collections.singleton(latest.getNode());
    }
 else {
      return conflicts;
    }
  }
 catch (  NoConflictResolvedYetException ex) {
    return null;
  }
}

