public TagTreePointer relocateKid(int kidIndex,TagTreePointer pointerToNewParent){
  if (getDocument() != pointerToNewParent.getDocument()) {
    throw new PdfException(KernelExceptionMessageConstant.TAG_CANNOT_BE_MOVED_TO_THE_ANOTHER_DOCUMENTS_TAG_STRUCTURE);
  }
  if (getCurrentStructElem().isFlushed()) {
    throw new PdfException(KernelExceptionMessageConstant.CANNOT_RELOCATE_TAG_WHICH_PARENT_IS_ALREADY_FLUSHED);
  }
  if (isPointingToSameTag(pointerToNewParent)) {
    if (kidIndex == pointerToNewParent.nextNewKidIndex) {
      return this;
    }
 else     if (kidIndex < pointerToNewParent.nextNewKidIndex) {
      pointerToNewParent.setNextNewKidIndex(pointerToNewParent.nextNewKidIndex - 1);
    }
  }
  if (getCurrentStructElem().getKids().get(kidIndex) == null) {
    throw new PdfException(KernelExceptionMessageConstant.CANNOT_RELOCATE_TAG_WHICH_IS_ALREADY_FLUSHED);
  }
  IStructureNode removedKid=getCurrentStructElem().removeKid(kidIndex,true);
  if (removedKid instanceof PdfStructElem) {
    pointerToNewParent.addNewKid((PdfStructElem)removedKid);
  }
 else   if (removedKid instanceof PdfMcr) {
    PdfMcr mcrKid=prepareMcrForMovingToNewParent((PdfMcr)removedKid,pointerToNewParent.getCurrentStructElem());
    pointerToNewParent.addNewKid(mcrKid);
  }
  return this;
}

private int[] createInitialLocals(){
  int[] initialLocals=new int[itsMaxLocals];
  int localsTop=0;
  if ((itsCurrentMethod.getFlags() & ACC_STATIC) == 0) {
    if ("<init>".equals(itsCurrentMethod.getName())) {
      initialLocals[localsTop++]=TypeInfo.UNINITIALIZED_THIS;
    }
 else {
      initialLocals[localsTop++]=TypeInfo.OBJECT(itsThisClassIndex);
    }
  }
  String type=itsCurrentMethod.getType();
  int lParenIndex=type.indexOf('(');
  int rParenIndex=type.indexOf(')');
  if (lParenIndex != 0 || rParenIndex < 0) {
    throw new IllegalArgumentException("bad method type");
  }
  int start=lParenIndex + 1;
  StringBuilder paramType=new StringBuilder();
  while (start < rParenIndex) {
switch (type.charAt(start)) {
case 'B':
case 'C':
case 'D':
case 'F':
case 'I':
case 'J':
case 'S':
case 'Z':
      paramType.append(type.charAt(start));
    ++start;
  break;
case 'L':
int end=type.indexOf(';',start) + 1;
String name=type.substring(start,end);
paramType.append(name);
start=end;
break;
case '[':
paramType.append('[');
++start;
continue;
}
String internalType=descriptorToInternalName(paramType.toString());
int typeInfo=TypeInfo.fromType(internalType,itsConstantPool);
initialLocals[localsTop++]=typeInfo;
if (TypeInfo.isTwoWords(typeInfo)) {
localsTop++;
}
paramType.setLength(0);
}
return initialLocals;
}

