    while (true) {
      ConnectionSetting setting=(ConnectionSetting)objStream.readObject();
      if (!emptySettingName.equals(setting.getName())) {
        list.put(setting.getName(),setting);
      }
    }
  }
 catch (  EOFException eof) {
  }
