    throw new IOException("Unrecognized class type " + cnfe.getMessage(),cnfe);
  }
catch (  ClassCastException cce) {
    throw new IOException("Unrecognized class type " + cce.getMessage(),cce);
  }
catch (  Throwable t) {
  }
 finally {
    if (objStream != null) {
      objStream.close();
    }
    if (in != null) {
      in.close();
    }
  }
  return list;
}

boolean equalGraphs(Object o1,Object o2){
  if (o1 == o2) {
    return true;
  }
 else   if (o1 == null || o2 == null) {
    return false;
  }
  final Object curr2=currentlyCompared.get(o1);
  if (curr2 == o2) {
    return true;
  }
 else   if (curr2 != null) {
    return false;
  }
  final Object prev2=knownEquals.get(o1);
  if (prev2 == o2) {
    return true;
  }
 else   if (prev2 != null) {
    return false;
  }
  final Object prev1=knownEquals.get(o2);
  assert prev1 != o1;
  if (prev1 != null) {
    return false;
  }
  currentlyCompared.put(o1,o2);
  final boolean eq=equalGraphsNoMemo(o1,o2);
  if (eq) {
    knownEquals.put(o1,o2);
    knownEquals.put(o2,o1);
  }
  currentlyCompared.remove(o1);
  return eq;
}

