public void getNegativeValues(final IntArrayList indexList,final FloatArrayList valueList){
  boolean fillIndexList=indexList != null;
  boolean fillValueList=valueList != null;
  if (fillIndexList)   indexList.clear();
  if (fillValueList)   valueList.clear();
  int rem=size % 2;
  if (rem == 1) {
    float value=getQuick(0);
    if (value < 0) {
      if (fillIndexList) {
        indexList.add(0);
      }
      if (fillValueList) {
        valueList.add(value);
      }
    }
  }
  for (int i=rem; i < size; i+=2) {
    float value=getQuick(i);
    if (value < 0) {
      if (fillIndexList) {
        indexList.add(i);
      }
      if (fillValueList) {
        valueList.add(value);
      }
    }
    value=getQuick(i + 1);
    if (value < 0) {
      if (fillIndexList) {
        indexList.add(i + 1);
      }
      if (fillValueList) {
        valueList.add(value);
      }
    }
  }
}

