protected static List extractFeMergeNode(Element filterElement,Element filteredElement,GraphicsNode filteredNode,Filter inputFilter,Map filterMap,BridgeContext ctx){
  List srcs=null;
  for (Node n=filterElement.getFirstChild(); n != null; n=n.getNextSibling()) {
    if (n.getNodeType() != Node.ELEMENT_NODE) {
      continue;
    }
    Element e=(Element)n;
    Bridge bridge=ctx.getBridge(e);
    if (bridge == null || !(bridge instanceof SVGFeMergeNodeElementBridge)) {
      continue;
    }
    Filter filter=((SVGFeMergeNodeElementBridge)bridge).createFilter(ctx,e,filteredElement,filteredNode,inputFilter,filterMap);
    if (filter != null) {
      if (srcs == null) {
        srcs=new LinkedList();
      }
      srcs.add(filter);
    }
  }
  return srcs;
}

public static CSSFontFace createCSSFontFace(CSSEngine eng,FontFaceRule ffr){
  StyleMap sm=ffr.getStyleMap();
  String familyName=getStringProp(sm,eng,SVGCSSEngine.FONT_FAMILY_INDEX);
  CSSFontFace ret=new CSSFontFace(familyName);
  Value v;
  v=sm.getValue(SVGCSSEngine.FONT_WEIGHT_INDEX);
  if (v != null)   ret.fontWeight=v.getCssText();
  v=sm.getValue(SVGCSSEngine.FONT_STYLE_INDEX);
  if (v != null)   ret.fontStyle=v.getCssText();
  v=sm.getValue(SVGCSSEngine.FONT_VARIANT_INDEX);
  if (v != null)   ret.fontVariant=v.getCssText();
  v=sm.getValue(SVGCSSEngine.FONT_STRETCH_INDEX);
  if (v != null)   ret.fontStretch=v.getCssText();
  v=sm.getValue(SVGCSSEngine.SRC_INDEX);
  ParsedURL base=ffr.getURL();
  if ((v != null) && (v != ValueConstants.NONE_VALUE)) {
    if (v.getCssValueType() == CSSValue.CSS_PRIMITIVE_VALUE) {
      ret.srcs=new LinkedList();
      ret.srcs.add(getSrcValue(v,base));
    }
 else     if (v.getCssValueType() == CSSValue.CSS_VALUE_LIST) {
      ret.srcs=new LinkedList();
      for (int i=0; i < v.getLength(); i++) {
        ret.srcs.add(getSrcValue(v.item(i),base));
      }
    }
  }
  return ret;
}

