public void setOwner(Object handle,Object owner){
  if (handle instanceof Feature && (owner == null || owner instanceof Classifier)) {
    setNamespace(handle,null);
    ((Feature)handle).setOwner((Classifier)owner);
    return;
  }
  if (handle instanceof TagDefinition && (owner == null || owner instanceof Stereotype)) {
    setNamespace(handle,null);
    ((TagDefinition)handle).setOwner((Stereotype)owner);
    if (owner != null) {
      ((Stereotype)owner).getDefinedTag().add((TagDefinition)handle);
    }
    return;
  }
  throw new IllegalArgumentException("handle: " + handle + " or owner: "+ owner);
}

